function check(input, actual, expected) {
  const [n] = input;
  if (typeof actual !== 'string' || actual.length !== n) return false;
  if (!/^[a-z]*$/.test(actual)) return false;
  const counts = new Map();
  for (const ch of actual) counts.set(ch, (counts.get(ch) ?? 0) + 1);
  for (const count of counts.values()) if (count % 2 === 0) return false;
  return true;
}

