function generateTheString(n) {
  // Split n into a big odd block of 'p' and a rest of 'z' that is empty or odd.
  for (let first = n; first >= 1; first--) {
    const rest = n - first;
    if (first % 2 === 1 && (rest === 0 || rest % 2 === 1)) {
      let text = '';
      for (let i = 0; i < first; i++) text += 'p';
      for (let i = 0; i < rest; i++) text += 'z';
      return text;
    }
  }
  return '';
}

